(function () {
  "use strict";
  var FN = "fn.smart-mail";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='mail']");
  if (!mount) { warn("mount [data-fn-mount='mail'] missing; skipping."); return; }
  var drafts = [];
  function status(msg, ok) {
    var el = mount.querySelector("[data-mail-status]");
    if (el) { el.textContent = msg; el.setAttribute("data-state", ok ? "ok" : "warn"); }
  }
  mount.innerHTML = ""
    + "<form data-mail-form novalidate>"
    + "<label>To<input type='email' data-mail-to required placeholder='name@example.com'></label>"
    + "<label>Subject<input type='text' data-mail-subject placeholder='Subject'></label>"
    + "<label>Message<textarea data-mail-body rows='4' placeholder='Write it like you would say it...'></textarea></label>"
    + "<button type='submit' class='naya-btn naya-btn--primary'>Send mail</button>"
    + "<p data-mail-status role='status' aria-live='polite'></p>"
    + "</form>";
  var form = mount.querySelector("[data-mail-form]");
  form.addEventListener("submit", function (ev) {
    ev.preventDefault();
    var to = mount.querySelector("[data-mail-to]").value.trim();
    var subject = mount.querySelector("[data-mail-subject]").value.trim();
    var body = mount.querySelector("[data-mail-body]").value.trim();
    if (!to || to.indexOf("@") < 1) { status("Add a valid recipient address first.", false); return; }
    var payload = { to: to, subject: subject, body: body };
    var page = window.NAYA_PAGE || {};
    if (page.bridge_url) {
      status("Sending...", true);
      fetch(page.bridge_url + "/mail/send", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      }).then(function (r) {
        if (!r.ok) { throw new Error("HTTP " + r.status); }
        return r.json();
      }).then(function () {
        drafts.push(payload);
        form.reset();
        status("Sent.", true);
      }).catch(function (err) {
        drafts.push(payload);
        status("Could not reach the mail backend (" + err.message + "). Draft kept on this device.", false);
      });
    } else {
      drafts.push(payload);
      status("Mail backend not configured (set window.NAYA_PAGE.bridge_url). Draft kept on this device.", false);
    }
  });
})();

(function () {
  "use strict";
  var FN = "fn.spaces";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='spaces']");
  if (!mount) { warn("mount [data-fn-mount='spaces'] missing; skipping."); return; }
  var spaces = [];
  try { spaces = JSON.parse(mount.getAttribute("data-spaces") || "[]"); }
  catch (e) { warn("data-spaces JSON invalid; using defaults."); }
  if (!spaces.length) { spaces = [{ name: "Builders" }, { name: "Learners" }, { name: "Makers" }]; }
  var joined = {};
  var filter = "";
  function render() {
    var list = mount.querySelector("[data-spaces-list]");
    if (!list) { return; }
    list.innerHTML = "";
    spaces.forEach(function (sp, i) {
      if (filter && String(sp.name).toLowerCase().indexOf(filter) < 0) { return; }
      var card = document.createElement("div");
      card.setAttribute("data-space-card", "");
      var title = document.createElement("strong");
      title.textContent = sp.name;
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "naya-btn naya-btn--secondary";
      btn.textContent = joined[i] ? "Leave" : "Join";
      btn.setAttribute("aria-pressed", joined[i] ? "true" : "false");
      (function (idx) {
        btn.addEventListener("click", function () { joined[idx] = !joined[idx]; render(); });
      })(i);
      card.appendChild(title);
      card.appendChild(document.createTextNode(" "));
      card.appendChild(btn);
      list.appendChild(card);
    });
    var count = mount.querySelector("[data-spaces-count]");
    if (count) {
      var n = Object.keys(joined).filter(function (k) { return joined[k]; }).length;
      count.textContent = n + " joined";
    }
  }
  mount.innerHTML = ""
    + "<label>Find a space<input type='search' data-spaces-filter placeholder='Search spaces...'></label>"
    + "<p data-spaces-count role='status'></p>"
    + "<div data-spaces-list></div>";
  mount.querySelector("[data-spaces-filter]").addEventListener("input", function (ev) {
    filter = ev.target.value.trim().toLowerCase();
    render();
  });
  render();
})();

(function () {
  "use strict";
  var FN = "fn.posting-feed";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='posting']");
  if (!mount) { warn("mount [data-fn-mount='posting'] missing; skipping."); return; }
  var posts = [];
  try { posts = JSON.parse(mount.getAttribute("data-posts") || "[]"); }
  catch (e) { warn("data-posts JSON invalid; starting empty."); }
  function note(msg) {
    var el = mount.querySelector("[data-feed-status]");
    if (el) { el.textContent = msg; }
  }
  function render() {
    var list = mount.querySelector("[data-feed-list]");
    list.innerHTML = "";
    posts.forEach(function (p) {
      var item = document.createElement("article");
      var head = document.createElement("p");
      head.textContent = p.author + (p.synced === false ? " - not synced" : "");
      var body = document.createElement("p");
      body.textContent = p.text;
      item.appendChild(head);
      item.appendChild(body);
      list.appendChild(item);
    });
  }
  mount.innerHTML = ""
    + "<form data-feed-form>"
    + "<label>Share an update<textarea data-feed-text rows='3' placeholder='What is happening in your world?'></textarea></label>"
    + "<button type='submit' class='naya-btn naya-btn--primary'>Post</button>"
    + "<p data-feed-status role='status' aria-live='polite'></p>"
    + "</form>"
    + "<div data-feed-list></div>";
  mount.querySelector("[data-feed-form]").addEventListener("submit", function (ev) {
    ev.preventDefault();
    var text = mount.querySelector("[data-feed-text]").value.trim();
    if (!text) { note("Write something first."); return; }
    var post = { author: "You", text: text, synced: true };
    var page = window.NAYA_PAGE || {};
    function publishLocal() {
      posts.unshift(post);
      render();
      mount.querySelector("[data-feed-form]").reset();
    }
    if (page.bridge_url) {
      note("Posting...");
      fetch(page.bridge_url + "/feed/post", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: text })
      }).then(function (r) {
        if (!r.ok) { throw new Error("HTTP " + r.status); }
        return r.json();
      }).then(function () {
        publishLocal();
        note("Posted.");
      }).catch(function (err) {
        post.synced = false;
        publishLocal();
        note("Backend unreachable (" + err.message + "). Kept locally, marked not synced.");
      });
    } else {
      post.synced = false;
      publishLocal();
      note("No feed backend configured (window.NAYA_PAGE.bridge_url). Post kept on this device.");
    }
  });
  render();
})();

(function () {
  "use strict";
  var FN = "fn.search";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='search']");
  if (!mount) { warn("mount [data-fn-mount='search'] missing; skipping."); return; }
  var targetSel = mount.getAttribute("data-search-target") || "[data-search-item]";
  var scopeSel = mount.getAttribute("data-search-scope");
  var scope = scopeSel ? document.querySelector(scopeSel) : document;
  if (!scope) { warn("search scope '" + scopeSel + "' not found; skipping."); return; }
  var input = mount.querySelector("input[type='search'], input[type='text']");
  if (!input) {
    input = document.createElement("input");
    input.type = "search";
    input.setAttribute("placeholder", "Search...");
    input.setAttribute("aria-label", "Search");
    mount.insertBefore(input, mount.firstChild);
  }
  function apply() {
    var q = input.value.trim().toLowerCase();
    var items = scope.querySelectorAll(targetSel);
    var shown = 0;
    for (var i = 0; i < items.length; i++) {
      var hit = !q || items[i].textContent.toLowerCase().indexOf(q) >= 0;
      items[i].hidden = !hit;
      if (hit) { shown++; }
    }
    var count = mount.querySelector("[data-search-count]");
    if (count) { count.textContent = shown + " of " + items.length; }
  }
  input.addEventListener("input", apply);
  apply();
})();

(function () {
  "use strict";
  var FN = "fn.gallery";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='gallery']");
  if (!mount) { warn("mount [data-fn-mount='gallery'] missing; skipping."); return; }
  var items = [];
  try { items = JSON.parse(mount.getAttribute("data-gallery-items") || "[]"); }
  catch (e) { warn("data-gallery-items JSON invalid; nothing to show."); }
  var selected = -1;
  function render() {
    mount.innerHTML = "";
    items.forEach(function (it, i) {
      var card = document.createElement("button");
      card.type = "button";
      card.className = "naya-btn naya-btn--ghost";
      card.setAttribute("aria-pressed", i === selected ? "true" : "false");
      var label = document.createElement("span");
      label.textContent = (it.label || "Item " + (i + 1)) + (it.note ? " - " + it.note : "");
      card.appendChild(label);
      (function (idx) {
        card.addEventListener("click", function () {
          selected = idx;
          render();
          var detail = { functionId: FN, index: idx, item: items[idx] };
          if (typeof CustomEvent === "function") {
            mount.dispatchEvent(new CustomEvent("naya:gallery-select", { bubbles: true, detail: detail }));
          }
        });
      })(i);
      mount.appendChild(card);
    });
  }
  render();
})();

(function () {
  "use strict";
  var FN = "fn.smart-tabs";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='tabs']");
  if (!mount) { warn("mount [data-fn-mount='tabs'] missing; skipping."); return; }
  var list = mount.querySelector("[role='tablist']");
  if (!list) { warn("no [role='tablist'] inside mount; skipping."); return; }
  var tabs = list.querySelectorAll("[role='tab']");
  if (!tabs.length) { warn("tablist has no [role='tab'] children; skipping."); return; }
  function panelFor(tab) {
    var id = tab.getAttribute("aria-controls");
    return id ? mount.querySelector("#" + id) : null;
  }
  function select(tab) {
    for (var i = 0; i < tabs.length; i++) {
      var active = tabs[i] === tab;
      tabs[i].setAttribute("aria-selected", active ? "true" : "false");
      tabs[i].tabIndex = active ? 0 : -1;
      var panel = panelFor(tabs[i]);
      if (panel) { panel.hidden = !active; }
    }
  }
  for (var i = 0; i < tabs.length; i++) {
    (function (tab) {
      tab.addEventListener("click", function () { select(tab); });
      tab.addEventListener("keydown", function (ev) {
        if (ev.key !== "ArrowRight" && ev.key !== "ArrowLeft") { return; }
        ev.preventDefault();
        var idx = Array.prototype.indexOf.call(tabs, tab);
        var next = (idx + (ev.key === "ArrowRight" ? 1 : tabs.length - 1)) % tabs.length;
        tabs[next].focus();
        select(tabs[next]);
      });
    })(tabs[i]);
  }
  select(list.querySelector("[aria-selected='true']") || tabs[0]);
})();

(function () {
  "use strict";
  var FN = "fn.reports";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='reports']");
  if (!mount) { warn("mount [data-fn-mount='reports'] missing; skipping."); return; }
  var data = {};
  try { data = JSON.parse(mount.getAttribute("data-reports") || "{}"); }
  catch (e) { warn("data-reports JSON invalid; showing empty periods."); }
  var periods = ["daily", "weekly", "monthly", "yearly"];
  var active = periods[0];
  function render() {
    var body = mount.querySelector("[data-reports-body]");
    body.innerHTML = "";
    var rows = data[active] || [];
    var total = 0;
    rows.forEach(function (r) {
      total += Number(r.value) || 0;
      var row = document.createElement("div");
      var k = document.createElement("strong");
      k.textContent = r.label;
      var v = document.createElement("span");
      v.textContent = ": " + String(r.value);
      row.appendChild(k);
      row.appendChild(v);
      body.appendChild(row);
    });
    var t = document.createElement("p");
    t.textContent = "Total: " + total + (rows.length ? " - average " + (total / rows.length).toFixed(1) : "");
    body.appendChild(t);
    var btns = mount.querySelectorAll("[data-period]");
    for (var i = 0; i < btns.length; i++) {
      btns[i].setAttribute("aria-pressed", btns[i].getAttribute("data-period") === active ? "true" : "false");
    }
  }
  var bar = document.createElement("div");
  bar.setAttribute("role", "group");
  bar.setAttribute("aria-label", "Report period");
  periods.forEach(function (p) {
    var b = document.createElement("button");
    b.type = "button";
    b.className = "naya-btn naya-btn--ghost";
    b.setAttribute("data-period", p);
    b.textContent = p.charAt(0).toUpperCase() + p.slice(1);
    (function (period) {
      b.addEventListener("click", function () { active = period; render(); });
    })(p);
    bar.appendChild(b);
  });
  var body = document.createElement("div");
  body.setAttribute("data-reports-body", "");
  mount.appendChild(bar);
  mount.appendChild(body);
  render();
})();

(function () {
  "use strict";
  var FN = "fn.intelligence-today";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='today']");
  if (!mount) { warn("mount [data-fn-mount='today'] missing; skipping."); return; }
  var items = [];
  try { items = JSON.parse(mount.getAttribute("data-today-items") || "[]"); }
  catch (e) { warn("data-today-items JSON invalid; nothing to show."); }
  var dismissed = {};
  function render() {
    var list = mount.querySelector("[data-today-list]");
    list.innerHTML = "";
    var shown = 0;
    items.forEach(function (it, i) {
      if (dismissed[i]) { return; }
      shown++;
      var li = document.createElement("li");
      var text = document.createElement("span");
      text.textContent = it;
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "naya-btn naya-btn--ghost";
      btn.setAttribute("aria-label", "Dismiss highlight");
      btn.textContent = "Dismiss";
      (function (idx) {
        btn.addEventListener("click", function () { dismissed[idx] = true; render(); });
      })(i);
      li.appendChild(text);
      li.appendChild(document.createTextNode(" "));
      li.appendChild(btn);
      list.appendChild(li);
    });
    if (!shown) { list.innerHTML = "<li>All caught up.</li>"; }
    var badge = mount.querySelector("[data-today-count]");
    if (badge) { badge.textContent = shown + " highlight" + (shown === 1 ? "" : "s"); }
  }
  mount.innerHTML = "<p data-today-count role='status'></p><ul data-today-list></ul>";
  render();
})();

(function () {
  "use strict";
  var FN = "fn.contacts";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='contacts']");
  if (!mount) { warn("mount [data-fn-mount='contacts'] missing; skipping."); return; }
  var contacts = [];
  try { contacts = JSON.parse(mount.getAttribute("data-contacts") || "[]"); }
  catch (e) { warn("data-contacts JSON invalid; starting empty."); }
