    + "<label>Search<input type='search' data-contacts-filter placeholder='Search contacts...'></label>"
    + "<form data-contacts-form>"
    + "<label>Name<input type='text' data-contact-name required></label>"
    + "<label>Note<input type='text' data-contact-note placeholder='How you know them'></label>"
