  mount.querySelector("[data-contacts-filter]").addEventListener("input", function (ev) {
    filter = ev.target.value.trim().toLowerCase();
    render();
  });
  mount.querySelector("[data-contacts-form]").addEventListener("submit", function (ev) {
    ev.preventDefault();
    var name = mount.querySelector("[data-contact-name]").value.trim();
    var note = mount.querySelector("[data-contact-note]").value.trim();
    if (!name) { return; }
    var c = { name: name, note: note };
    var page = window.NAYA_PAGE || {};
    if (page.bridge_url) {
      fetch(page.bridge_url + "/contacts/add", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(c)
      }).then(function (r) {
        if (!r.ok) { throw new Error("HTTP " + r.status); }
        return r.json();
      }).catch(function (err) {
