(function () {
  "use strict";
  var FN = "fn.booking";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='booking']");
  if (!mount) { warn("mount [data-fn-mount='booking'] missing; skipping."); return; }
  var slots = [];
  try { slots = JSON.parse(mount.getAttribute("data-slots") || "[]"); }
  catch (e) { warn("data-slots JSON invalid; using defaults."); }
  if (!slots.length) { slots = ["09:00", "11:00", "14:00", "16:00"]; }
  var chosen = null;
  var saved = [];
  function status(msg, ok) {
    var el = mount.querySelector("[data-booking-status]");
    if (el) { el.textContent = msg; el.setAttribute("data-state", ok ? "ok" : "warn"); }
  }
  function renderSaved() {
    var list = mount.querySelector("[data-booking-saved]");
    list.innerHTML = "";
    saved.forEach(function (s) {
      var li = document.createElement("li");
      li.textContent = s.date + " " + s.slot + " - " + s.name + (s.confirmed ? " (confirmed)" : " (saved on this device)");
      list.appendChild(li);
    });
  }
  var html = "<label>Date<input type='date' data-booking-date required></label>"
    + "<div data-booking-slots role='group' aria-label='Time slots'>";
  slots.forEach(function (s) {
    html += "<button type='button' class='naya-btn naya-btn--ghost' data-slot='" + s + "'>" + s + "</button>";
  });
  html += "</div>"
    + "<label>Name<input type='text' data-booking-name required placeholder='Your name'></label>"
    + "<button type='button' class='naya-btn naya-btn--primary' data-booking-confirm>Confirm booking</button>"
    + "<p data-booking-status role='status' aria-live='polite'></p>"
    + "<ul data-booking-saved></ul>";
  mount.innerHTML = html;
  var slotBtns = mount.querySelectorAll("[data-slot]");
  for (var i = 0; i < slotBtns.length; i++) {
    (function (b) {
      b.addEventListener("click", function () {
        chosen = b.getAttribute("data-slot");
        for (var j = 0; j < slotBtns.length; j++) {
          slotBtns[j].setAttribute("aria-pressed", slotBtns[j] === b ? "true" : "false");
        }
      });
    })(slotBtns[i]);
  }
  mount.querySelector("[data-booking-confirm]").addEventListener("click", function () {
    var date = mount.querySelector("[data-booking-date]").value;
    var name = mount.querySelector("[data-booking-name]").value.trim();
    if (!date || !chosen || !name) { status("Pick a date, a time slot, and add your name.", false); return; }
    var req = { date: date, slot: chosen, name: name, confirmed: false };
    var page = window.NAYA_PAGE || {};
    function keepLocal(confirmed) {
      req.confirmed = confirmed;
      saved.push(req);
      renderSaved();
    }
    if (page.bridge_url) {
      status("Confirming...", true);
      fetch(page.bridge_url + "/booking/confirm", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(req)
      }).then(function (r) {
        if (!r.ok) { throw new Error("HTTP " + r.status); }
        return r.json();
      }).then(function () {
        keepLocal(true);
        status("Booked.", true);
      }).catch(function (err) {
        keepLocal(false);
        status("Booking backend unreachable (" + err.message + "). Request saved on this device.", false);
      });
    } else {
      keepLocal(false);
      status("No booking backend configured (window.NAYA_PAGE.bridge_url). Request saved on this device.", false);
    }
  });
})();

(function () {
  "use strict";
  var FN = "fn.rsvp";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='rsvp']");
  if (!mount) { warn("mount [data-fn-mount='rsvp'] missing; skipping."); return; }
  var attendees = [];
  function tally() {
    var yes = attendees.filter(function (a) { return a.attending; }).length;
    var guests = attendees.reduce(function (n, a) { return n + (a.attending ? (Number(a.count) || 1) : 0); }, 0);
    var el = mount.querySelector("[data-rsvp-tally]");
    if (el) { el.textContent = yes + " attending - " + guests + " guests"; }
  }
  function status(msg) {
    var el = mount.querySelector("[data-rsvp-status]");
    if (el) { el.textContent = msg; }
  }
  mount.innerHTML = ""
    + "<form data-rsvp-form>"
    + "<label>Name<input type='text' data-rsvp-name required></label>"
    + "<label>Guests<input type='number' data-rsvp-count min='1' value='1'></label>"
    + "<label><input type='checkbox' data-rsvp-yes checked> I will attend</label>"
    + "<button type='submit' class='naya-btn naya-btn--primary'>RSVP</button>"
    + "<p data-rsvp-status role='status' aria-live='polite'></p>"
    + "</form>"
    + "<p data-rsvp-tally role='status'></p><ul data-rsvp-list></ul>";
  mount.querySelector("[data-rsvp-form]").addEventListener("submit", function (ev) {
    ev.preventDefault();
    var a = {
      name: mount.querySelector("[data-rsvp-name]").value.trim(),
      count: mount.querySelector("[data-rsvp-count]").value,
      attending: mount.querySelector("[data-rsvp-yes]").checked
    };
    if (!a.name) { status("Add your name first."); return; }
    var page = window.NAYA_PAGE || {};
    if (page.bridge_url) {
      fetch(page.bridge_url + "/rsvp/submit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(a)
      }).then(function (r) {
        if (!r.ok) { throw new Error("HTTP " + r.status); }
        return r.json();
      }).catch(function (err) {
        warn("rsvp backend unreachable (" + err.message + "); kept locally.");
      });
    }
    attendees.push(a);
    var li = document.createElement("li");
    li.textContent = a.name + (a.attending ? " - attending" : " - can't make it") + " (" + (Number(a.count) || 1) + ")";
    mount.querySelector("[data-rsvp-list]").appendChild(li);
    mount.querySelector("[data-rsvp-form]").reset();
    tally();
    status("RSVP recorded" + (page.bridge_url ? "." : " on this device (no backend configured)."));
  });
  tally();
})();

(function () {
  "use strict";
  var FN = "fn.countdown";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='countdown']");
  if (!mount) { warn("mount [data-fn-mount='countdown'] missing; skipping."); return; }
  var target = mount.getAttribute("data-target");
  var t = Date.parse(target || "");
  if (!target || isNaN(t)) {
    warn("data-target missing or not a valid date (" + target + "); skipping.");
    return;
  }
  function pad(n) { return (n < 10 ? "0" : "") + n; }
  function tick() {
    var diff = t - Date.now();
    if (diff <= 0) { mount.textContent = "It's time."; return false; }
    var s = Math.floor(diff / 1000);
    var d = Math.floor(s / 86400); s -= d * 86400;
    var h = Math.floor(s / 3600); s -= h * 3600;
    var m = Math.floor(s / 60); s -= m * 60;
    mount.textContent = d + "d " + pad(h) + "h " + pad(m) + "m " + pad(s) + "s";
    return true;
  }
  if (tick()) { setInterval(tick, 1000); }
})();

(function () {
  "use strict";
  var FN = "fn.product-checkout";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='checkout']");
  if (!mount) { warn("mount [data-fn-mount='checkout'] missing; skipping."); return; }
  var products = [];
  try { products = JSON.parse(mount.getAttribute("data-products") || "[]"); }
  catch (e) { warn("data-products JSON invalid."); }
  if (!products.length) { warn("no products in data-products; nothing to sell."); return; }
  function money(cents) { return "$" + (cents / 100).toFixed(2); }
  var qty = {};
  function total() {
    return products.reduce(function (n, p, i) {
      return n + (Number(p.price_cents) || 0) * (qty[i] || 0);
    }, 0);
  }
  function renderSummary() {
    var el = mount.querySelector("[data-checkout-total]");
    if (el) { el.textContent = "Total: " + money(total()); }
  }
  function status(msg, ok) {
    var el = mount.querySelector("[data-checkout-status]");
    if (el) { el.textContent = msg; el.setAttribute("data-state", ok ? "ok" : "warn"); }
  }
  var list = document.createElement("div");
  list.setAttribute("data-checkout-list", "");
  products.forEach(function (p, i) {
    var row = document.createElement("div");
    var name = document.createElement("strong");
    name.textContent = p.name;
    var price = document.createElement("span");
    price.textContent = " " + money(Number(p.price_cents) || 0) + " ";
    var minus = document.createElement("button");
    minus.type = "button";
    minus.className = "naya-btn naya-btn--ghost";
    minus.textContent = "-";
    minus.setAttribute("aria-label", "Remove one " + p.name);
    var q = document.createElement("span");
    q.textContent = " 0 ";
    var plus = document.createElement("button");
    plus.type = "button";
    plus.className = "naya-btn naya-btn--ghost";
    plus.textContent = "+";
    plus.setAttribute("aria-label", "Add one " + p.name);
    (function (idx, qEl) {
      minus.addEventListener("click", function () {
        qty[idx] = Math.max(0, (qty[idx] || 0) - 1);
        qEl.textContent = " " + qty[idx] + " ";
        renderSummary();
      });
      plus.addEventListener("click", function () {
        qty[idx] = (qty[idx] || 0) + 1;
        qEl.textContent = " " + qty[idx] + " ";
        renderSummary();
      });
    })(i, q);
    row.appendChild(name);
    row.appendChild(price);
    row.appendChild(minus);
    row.appendChild(q);
    row.appendChild(plus);
    list.appendChild(row);
  });
  var summary = document.createElement("p");
  summary.setAttribute("data-checkout-total", "");
  summary.setAttribute("role", "status");
  var pay = document.createElement("button");
  pay.type = "button";
  pay.className = "naya-btn naya-btn--primary";
  pay.textContent = "Checkout";
  var st = document.createElement("p");
  st.setAttribute("data-checkout-status", "");
  st.setAttribute("role", "status");
  st.setAttribute("aria-live", "polite");
  pay.addEventListener("click", function () {
    var lines = [];
    products.forEach(function (p, i) {
      if (qty[i] > 0) { lines.push({ name: p.name, price_cents: Number(p.price_cents) || 0, qty: qty[i] }); }
    });
    if (!lines.length) { status("Add at least one item first.", false); return; }
    var page = window.NAYA_PAGE || {};
    if (page.bridge_url) {
      status("Starting checkout...", true);
      fetch(page.bridge_url + "/checkout/create", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ items: lines, total_cents: total() })
      }).then(function (r) {
        if (!r.ok) { throw new Error("HTTP " + r.status); }
        return r.json();
      }).then(function (resp) {
        if (resp && resp.checkout_url) { window.location.href = resp.checkout_url; }
        else { status("Checkout created. Complete payment on the provider page.", true); }
      }).catch(function (err) {
        status("Checkout backend unreachable (" + err.message + "). No charge was made.", false);
      });
    } else {
      status("Checkout is not connected (window.NAYA_PAGE.bridge_url is unset). No charge was made - connect a payment backend to go live.", false);
    }
  });
  mount.appendChild(list);
  mount.appendChild(summary);
  mount.appendChild(pay);
  mount.appendChild(st);
  renderSummary();
})();

(function () {
  "use strict";
  var FN = "fn.signup";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='signup']");
  if (!mount) { warn("mount [data-fn-mount='signup'] missing; skipping."); return; }
  var listName = mount.getAttribute("data-list") || "updates";
  function status(msg, ok) {
    var el = mount.querySelector("[data-signup-status]");
    if (el) { el.textContent = msg; el.setAttribute("data-state", ok ? "ok" : "warn"); }
  }
  mount.innerHTML = ""
    + "<form data-signup-form novalidate>"
    + "<label>Name<input type='text' data-signup-name placeholder='Your name'></label>"
    + "<label>Email<input type='email' data-signup-email required placeholder='you@example.com'></label>"
    + "<button type='submit' class='naya-btn naya-btn--primary'>Sign up</button>"
    + "<p data-signup-status role='status' aria-live='polite'></p>"
    + "</form>";
  mount.querySelector("[data-signup-form]").addEventListener("submit", function (ev) {
    ev.preventDefault();
    var email = mount.querySelector("[data-signup-email]").value.trim();
    var name = mount.querySelector("[data-signup-name]").value.trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      status("Enter a valid email address.", false);
      return;
    }
    var payload = { name: name, email: email, list: listName };
    var page = window.NAYA_PAGE || {};
    if (page.bridge_url) {
      fetch(page.bridge_url + "/signup/submit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      }).then(function (r) {
        if (!r.ok) { throw new Error("HTTP " + r.status); }
        return r.json();
      }).then(function () {
        status("You're in. Welcome" + (name ? ", " + name : "") + ".", true);
      }).catch(function (err) {
        status("Signup backend unreachable (" + err.message + "). Please try again later.", false);
      });
    } else {
      status("You're on the list (kept on this device - no signup backend configured).", true);
    }
  });
})();

(function () {
  "use strict";
  var FN = "fn.pwa-install";
  function warn(m) { try { console.warn("[naya:" + FN + "] " + m); } catch (e) {} }
  var mount = document.querySelector("[data-fn-mount='pwa']");
  if (!mount) { warn("mount [data-fn-mount='pwa'] missing; skipping."); return; }
  var deferred = null;
  var btn = document.createElement("button");
  btn.type = "button";
  btn.className = "naya-btn naya-btn--primary";
  btn.textContent = "Install app";
  var note = document.createElement("p");
  note.setAttribute("role", "status");
  function installed() {
    return (window.matchMedia && window.matchMedia("(display-mode: standalone)").matches)
      || window.navigator.standalone === true;
  }
  function refresh() {
    if (installed()) {
      btn.disabled = true;
      btn.textContent = "Installed";
      note.textContent = "This app is installed.";
    } else if (!deferred) {
      note.textContent = "To install: open your browser menu and choose Add to Home Screen / Install app. The intake icon step provides the app icon.";
    } else {
      note.textContent = "";
    }
  }
  window.addEventListener("beforeinstallprompt", function (ev) {
    ev.preventDefault();
    deferred = ev;
    refresh();
  });
  window.addEventListener("appinstalled", function () {
    deferred = null;
    refresh();
  });
  btn.addEventListener("click", function () {
    if (!deferred) { refresh(); return; }
    deferred.prompt();
    if (deferred.userChoice && typeof deferred.userChoice.then === "function") {
      deferred.userChoice.then(function () { deferred = null; refresh(); });
    } else {
      deferred = null;
      refresh();
    }
  });
  mount.appendChild(btn);
  mount.appendChild(note);
  refresh();
})();
